INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6206193, 916647, 30861, '<td valign="top">That''s hilarious! One almost suspects you of having DRAWN that expression onto the poor beast :-)</td>', 'That''s hilarious! One almost suspects you of having DRAWN that expression onto the poor beast :-)', '2010-11-01 00:12:01.000000', NULL, 1),
(6206210, 916956, 47974, '<td valign="top">I feel the processing on the deer ruins the photo.  I don''t care for the plastic look that they have.  Some different processing could have made this a very dramatic photograph.</td>', 'I feel the processing on the deer ruins the photo.  I don''t care for the plastic look that they have.  Some different processing could have made this a very dramatic photograph.', '2010-11-01 00:17:02.000000', NULL, 1),
(6206214, 916992, 47974, '<td valign="top">Less DOF would have made this a wonderful shot.  Great focus on the eye and nice detail in the feathers.</td>', 'Less DOF would have made this a wonderful shot.  Great focus on the eye and nice detail in the feathers.', '2010-11-01 00:17:49.000000', NULL, 1),
(6206218, 917172, 47974, '<td valign="top">The deer in the background is distracting.  Nice focus on the eyes and good detail in the fur.</td>', 'The deer in the background is distracting.  Nice focus on the eyes and good detail in the fur.', '2010-11-01 00:18:58.000000', NULL, 1),
(6206227, 916766, 47974, '<td valign="top">Really good job at blacking out the background but they eye is a little soft.</td>', 'Really good job at blacking out the background but they eye is a little soft.', '2010-11-01 00:20:20.000000', NULL, 1),
(6206228, 917461, 51379, '<td valign="top">This is very well done, I really like the feel of this. It should score fairly high, the only minor fault is the tufts on the ears. They are a very distinguishing mark of the Lynx. I would have predicted a Ribbon here if they were not cut off.<br/>Good Luck with this I hope it does well for you.</td>', 'This is very well done, I really like the feel of this. It should score fairly high, the only minor fault is the tufts on the ears. They are a very distinguishing mark of the Lynx. I would have predicted a Ribbon here if they were not cut off.Good Luck with this I hope it does well for you.', '2010-11-01 00:20:20.000000', NULL, 1),
(6206236, 917395, 47974, '<td valign="top">To bad some weeds are in front of his head.  Wonderful capture.</td>', 'To bad some weeds are in front of his head.  Wonderful capture.', '2010-11-01 00:21:35.000000', NULL, 1),
(6206240, 917021, 47974, '<td valign="top">A bigger size photograph would have helped this image a lot.</td>', 'A bigger size photograph would have helped this image a lot.', '2010-11-01 00:22:41.000000', NULL, 1),
(6206255, 917370, 674, '<td valign="top">6 would have given higher but the tight cropping has lessened the impact.</td>', '6 would have given higher but the tight cropping has lessened the impact.', '2010-11-01 00:27:19.000000', NULL, 1),
(6206338, 917419, 119419, '<td valign="top">very clever, whether is''s a mollusc or a worm, and still alive - irrelevant.<br/>I love the image. It moves and grooves and it aint dead.8</td>', 'very clever, whether is''s a mollusc or a worm, and still alive - irrelevant.I love the image. It moves and grooves and it aint dead.8', '2010-11-01 01:33:41.000000', NULL, 1),
(6206339, 917051, 119419, '<td valign="top">Praise the Lord, nice capture, the wave lines compliment the bird lines beautifully</td>', 'Praise the Lord, nice capture, the wave lines compliment the bird lines beautifully', '2010-11-01 01:35:05.000000', NULL, 1),
(6206340, 917147, 119419, '<td valign="top">Lovely tones</td>', 'Lovely tones', '2010-11-01 01:35:51.000000', NULL, 1),
(6206341, 917502, 119419, '<td valign="top">Like the shot, dof good</td>', 'Like the shot, dof good', '2010-11-01 01:37:12.000000', NULL, 1),
(6206344, 916636, 119419, '<td valign="top">This a really good image but where is the wild animal?</td>', 'This a really good image but where is the wild animal?', '2010-11-01 01:40:20.000000', NULL, 1),
(6206346, 917235, 119419, '<td valign="top">Almost surreal with that background</td>', 'Almost surreal with that background', '2010-11-01 01:42:03.000000', NULL, 1),
(6206347, 917482, 119419, '<td valign="top">Wow, not only a great shot but gets the sympathy vote, nice</td>', 'Wow, not only a great shot but gets the sympathy vote, nice', '2010-11-01 01:42:55.000000', NULL, 1),
(6206348, 916704, 119419, '<td valign="top">They''ve got holters on !</td>', 'They''ve got holters on !', '2010-11-01 01:44:08.000000', NULL, 1),
(6206350, 916569, 119419, '<td valign="top">great capture, dof a bit shallow, I would have takenn out the little green plant up front. Good effort, I know these things are so quick.</td>', 'great capture, dof a bit shallow, I would have takenn out the little green plant up front. Good effort, I know these things are so quick.', '2010-11-01 01:46:41.000000', NULL, 1),
(6206352, 916647, 119419, '<td valign="top">very comical expression and body position</td>', 'very comical expression and body position', '2010-11-01 01:48:16.000000', NULL, 1),
(6206355, 917080, 119419, '<td valign="top">What a gorgeous image in this style, probably in top 5 for sure</td>', 'What a gorgeous image in this style, probably in top 5 for sure', '2010-11-01 01:49:52.000000', NULL, 1),
(6206357, 917160, 119419, '<td valign="top">Shetland ponies? v. cute</td>', 'Shetland ponies? v. cute', '2010-11-01 01:50:59.000000', NULL, 1),
(6206364, 917246, 119419, '<td valign="top">a bug? good shot but not a wild animal</td>', 'a bug? good shot but not a wild animal', '2010-11-01 01:57:08.000000', NULL, 1),
(6206365, 917231, 119419, '<td valign="top">nice high tone, good active moment</td>', 'nice high tone, good active moment', '2010-11-01 01:58:59.000000', NULL, 1),
(6206366, 916313, 119419, '<td valign="top">lovely interpretation, lucky we have titles though, interesting perspective</td>', 'lovely interpretation, lucky we have titles though, interesting perspective', '2010-11-01 02:00:07.000000', NULL, 1),
(6206367, 916407, 119419, '<td valign="top">go the aussies, I''ll give that me 5 cents ;)</td>', 'go the aussies, I''ll give that me 5 cents ;)', '2010-11-01 02:01:00.000000', NULL, 1),
(6206368, 916826, 119419, '<td valign="top">good capture, for a sec I thought they were going right to left. great colour &amp; tone</td>', 'good capture, for a sec I thought they were going right to left. great colour & tone', '2010-11-01 02:03:30.000000', NULL, 1),
(6206369, 917024, 119419, '<td valign="top">the jet stream finishes it off nicely, good perspective all round</td>', 'the jet stream finishes it off nicely, good perspective all round', '2010-11-01 02:04:31.000000', NULL, 1),
(6206370, 916889, 119419, '<td valign="top">love the mood here, though the flora overshadows the fauna. But it still works fine</td>', 'love the mood here, though the flora overshadows the fauna. But it still works fine', '2010-11-01 02:06:30.000000', NULL, 1),
(6206375, 916728, 119419, '<td valign="top">David I presume. Always a lovely subject, presented well. And the other side in the free challenge.</td>', 'David I presume. Always a lovely subject, presented well. And the other side in the free challenge.', '2010-11-01 02:08:55.000000', NULL, 1),
(6206389, 917505, 40391, '<td valign="top">I''m only 10 images into voting so far but I''m already looking at a ribbon finishing shot.  This is fantastic! 10 and fav.</td>', 'I''m only 10 images into voting so far but I''m already looking at a ribbon finishing shot.  This is fantastic! 10 and fav.', '2010-11-01 02:44:30.000000', NULL, 1),
(6206394, 917419, 40391, '<td valign="top">You got my attention!  I''m guessing it''s a dandelion but that''s not important as you''re representing a fossil with your image and title.  I don''t expect this to do much better than my own entry but I really like it and have given you a 7.  Very nice.</td>', 'You got my attention!  I''m guessing it''s a dandelion but that''s not important as you''re representing a fossil with your image and title.  I don''t expect this to do much better than my own entry but I really like it and have given you a 7.  Very nice.', '2010-11-01 02:50:37.000000', NULL, 1),
(6206399, 917103, 122149, '<td valign="top">u caught them in the funniest positions. the one on the bottom looks like is hailing  a cab. nice photo.</td>', 'u caught them in the funniest positions. the one on the bottom looks like is hailing  a cab. nice photo.', '2010-11-01 03:07:26.000000', NULL, 1),
(6206400, 917247, 122149, '<td valign="top">lol gobble gobble.</td>', 'lol gobble gobble.', '2010-11-01 03:11:38.000000', NULL, 1),
(6206408, 916889, 40391, '<td valign="top">This is a truly a beautiful image. 9.</td>', 'This is a truly a beautiful image. 9.', '2010-11-01 03:30:41.000000', NULL, 1),
(6206413, 917504, 40391, '<td valign="top">I''m appreciating the not so traditional wildlife images such as this.  I almost entered someting similar <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=916610" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/40000-44999/40391/120/Copyrighted_Image_Reuse_Prohibited_916610.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/40000-44999/40391/120/Copyrighted_Image_Reuse_Prohibited_916610.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/40000-44999/40391/120/Copyrighted_Image_Reuse_Prohibited_916610.jpg"/></a> <br/> <br/>I like the motion blur and colours - quite beautiful.  8.</td>', 'I''m appreciating the not so traditional wildlife images such as this.  I almost entered someting similar   I like the motion blur and colours - quite beautiful.  8.', '2010-11-01 03:45:56.000000', NULL, 1),
(6206418, 916704, 40391, '<td valign="top">I like the grain and action of the shot.  The fence and head gear sort of gives it away that these aren''t quite wild horses so I''ve knocked of a couple of points. 5.</td>', 'I like the grain and action of the shot.  The fence and head gear sort of gives it away that these aren''t quite wild horses so I''ve knocked of a couple of points. 5.', '2010-11-01 03:58:42.000000', NULL, 1),
(6206420, 917235, 40391, '<td valign="top">What a wonderful shot.  The lighting and exposure are perfect and the composition is great.  The large tree in the distance tops off a great image.  10!</td>', 'What a wonderful shot.  The lighting and exposure are perfect and the composition is great.  The large tree in the distance tops off a great image.  10!', '2010-11-01 04:02:59.000000', NULL, 1),
(6206423, 917108, 40391, '<td valign="top">He he, cute shoehorn but I think you know this will not score highly. A vote of 3 for the nice composition and honest title.</td>', 'He he, cute shoehorn but I think you know this will not score highly. A vote of 3 for the nice composition and honest title.', '2010-11-01 04:06:36.000000', NULL, 1),
(6206428, 917502, 40391, '<td valign="top">Doesn''t quite meet the challenge description but I do like the shot and processing.  Is this a Black House Spider?  They''re more common here in Sydney than just about any other spider and yet I haven''t taken a single shot of one. I think you''ve just inspired me. 5.</td>', 'Doesn''t quite meet the challenge description but I do like the shot and processing.  Is this a Black House Spider?  They''re more common here in Sydney than just about any other spider and yet I haven''t taken a single shot of one. I think you''ve just inspired me. 5.', '2010-11-01 04:19:06.000000', NULL, 1),
(6206429, 917186, 40391, '<td valign="top">Don''t see any cages there and the trees do look African.  She pops nicely against the similar coloured grass.  Good composition too. 8.</td>', 'Don''t see any cages there and the trees do look African.  She pops nicely against the similar coloured grass.  Good composition too. 8.', '2010-11-01 04:20:50.000000', NULL, 1),
(6206432, 916313, 40391, '<td valign="top">I''m enjoying the number of more abstract entries in this challenge and this is one of the best.  The lighting works very well for me. 8.</td>', 'I''m enjoying the number of more abstract entries in this challenge and this is one of the best.  The lighting works very well for me. 8.', '2010-11-01 04:23:22.000000', NULL, 1),
(6206452, 916645, 674, '<td valign="top">lovely shot where in Namibia was this taken? I believe they raise there body temp to survive the desert heat!</td>', 'lovely shot where in Namibia was this taken? I believe they raise there body temp to survive the desert heat!', '2010-11-01 05:04:34.000000', NULL, 1),
(6206453, 917287, 674, '<td valign="top">Goodness he looks grumpy!</td>', 'Goodness he looks grumpy!', '2010-11-01 05:05:30.000000', NULL, 1),
(6206471, 917281, 14867, '<td valign="top">Unfortunately unsharp....</td>', 'Unfortunately unsharp....', '2010-11-01 06:18:29.000000', NULL, 1),
(6206476, 917505, 36606, '<td valign="top">possible winner here. great shot, so vibrant.</td>', 'possible winner here. great shot, so vibrant.', '2010-11-01 06:38:05.000000', NULL, 1),
(6206515, 917347, 112159, '<td valign="top">Obviously a good moment caught here, but they are clearly standing in loose hay and the fence is visible. Supposed to be "non-domesticated... living in a natural environment."</td>', 'Obviously a good moment caught here, but they are clearly standing in loose hay and the fence is visible. Supposed to be "non-domesticated... living in a natural environment."', '2010-11-01 08:12:57.000000', NULL, 1),
(6206517, 917417, 112159, '<td valign="top">Nice dof, great clarity.</td>', 'Nice dof, great clarity.', '2010-11-01 08:13:30.000000', NULL, 1),
(6206520, 916636, 112159, '<td valign="top">I like the idea here, but I don''t think relating to wildlife is sufficient for the comp.</td>', 'I like the idea here, but I don''t think relating to wildlife is sufficient for the comp.', '2010-11-01 08:15:47.000000', NULL, 1),
(6206523, 916645, 112159, '<td valign="top">Nice lighting and colour tone.</td>', 'Nice lighting and colour tone.', '2010-11-01 08:18:32.000000', NULL, 1),
(6206524, 917108, 112159, '<td valign="top">Nice lighting, but...</td>', 'Nice lighting, but...', '2010-11-01 08:22:06.000000', NULL, 1),
(6206525, 916794, 112159, '<td valign="top">Nice to see a true wildlife shot!</td>', 'Nice to see a true wildlife shot!', '2010-11-01 08:24:49.000000', NULL, 1),
(6206527, 917186, 112159, '<td valign="top">This genuinely looks real; not in a zoo.</td>', 'This genuinely looks real; not in a zoo.', '2010-11-01 08:26:32.000000', NULL, 1),
(6206528, 916735, 112159, '<td valign="top">So cute, I wish it were sharper.</td>', 'So cute, I wish it were sharper.', '2010-11-01 08:28:13.000000', NULL, 1),
(6206532, 916704, 112159, '<td valign="top">Supposed to be "non-domesticated... living in a natural environment."</td>', 'Supposed to be "non-domesticated... living in a natural environment."', '2010-11-01 08:36:15.000000', NULL, 1),
(6206552, 916636, 47974, '<td valign="top">DMC</td>', 'DMC', '2010-11-01 08:44:40.000000', NULL, 1),
(6206555, 916889, 47974, '<td valign="top">Trying to figure out what kind of animal it is.</td>', 'Trying to figure out what kind of animal it is.', '2010-11-01 08:45:05.000000', NULL, 1),
(6206557, 917108, 47974, '<td valign="top">DMC</td>', 'DMC', '2010-11-01 08:45:16.000000', NULL, 1),
(6206559, 916704, 47974, '<td valign="top">DMC</td>', 'DMC', '2010-11-01 08:45:28.000000', NULL, 1),
(6206568, 917246, 47974, '<td valign="top">The composition and background are just wonderful.  One of my favorites from the challenge.  I hope you get the votes you deserve for this, just afraid people will vote down insect photos.</td>', 'The composition and background are just wonderful.  One of my favorites from the challenge.  I hope you get the votes you deserve for this, just afraid people will vote down insect photos.', '2010-11-01 08:52:50.000000', NULL, 1),
(6206569, 916794, 47974, '<td valign="top">Beautiful capture.</td>', 'Beautiful capture.', '2010-11-01 08:53:14.000000', NULL, 1),
(6206571, 916728, 47974, '<td valign="top">Perfect lighting on this shot.  I would love to take a photo like this.</td>', 'Perfect lighting on this shot.  I would love to take a photo like this.', '2010-11-01 08:54:28.000000', NULL, 1),
(6206574, 917482, 47974, '<td valign="top">Love the processing on this photo.  Makes him look so sad.  One of the top photos in the challenge</td>', 'Love the processing on this photo.  Makes him look so sad.  One of the top photos in the challenge', '2010-11-01 08:55:42.000000', NULL, 1),
(6206576, 917461, 47974, '<td valign="top">A beautiful capture of a beautiful animal.</td>', 'A beautiful capture of a beautiful animal.', '2010-11-01 08:56:25.000000', NULL, 1),
(6206577, 917347, 47974, '<td valign="top">While they are wild animals judging by the high fence in the background I am thinking they are wild but not free.</td>', 'While they are wild animals judging by the high fence in the background I am thinking they are wild but not free.', '2010-11-01 08:57:26.000000', NULL, 1),
(6206580, 917015, 47974, '<td valign="top">Excellent capture.  The symmetry between the birds really make this photograph.  Outstanding detail in the feathers.  One of my top photos of the challenge.</td>', 'Excellent capture.  The symmetry between the birds really make this photograph.  Outstanding detail in the feathers.  One of my top photos of the challenge.', '2010-11-01 08:58:43.000000', NULL, 1),
(6206581, 917084, 674, '<td valign="top">a pity the habitat is not natural</td>', 'a pity the habitat is not natural', '2010-11-01 08:59:13.000000', NULL, 1),
(6206584, 917051, 47974, '<td valign="top">My favorite of the challenge.  I love the simplicity of the shot, the detail in the feathers and the conversion.</td>', 'My favorite of the challenge.  I love the simplicity of the shot, the detail in the feathers and the conversion.', '2010-11-01 09:00:01.000000', NULL, 1),
(6206587, 916645, 47974, '<td valign="top">Perfect DOF.  Feel like the orange could have been subdued some, almost overpowers the photograph.</td>', 'Perfect DOF.  Feel like the orange could have been subdued some, almost overpowers the photograph.', '2010-11-01 09:03:49.000000', NULL, 1),
(6206589, 916579, 47974, '<td valign="top">Perfect DOF and sharpness in the birds head.  Something about the foreground is distracting, just can''t place my finger on it.  Coming back to leave comment did cause me to bump up my vote :-)</td>', 'Perfect DOF and sharpness in the birds head.  Something about the foreground is distracting, just can''t place my finger on it.  Coming back to leave comment did cause me to bump up my vote :-)', '2010-11-01 09:05:36.000000', NULL, 1),
(6206641, 917024, 65234, '<td valign="top">Sunbathing gulls?</td>', 'Sunbathing gulls?', '2010-11-01 09:46:50.000000', NULL, 1),
(6206644, 916889, 65234, '<td valign="top">Bear?  Generally speaking I like to see my wildlife clearly, but the hint of a bear is kind of interesting here with the fog.</td>', 'Bear?  Generally speaking I like to see my wildlife clearly, but the hint of a bear is kind of interesting here with the fog.', '2010-11-01 09:47:55.000000', NULL, 1),
(6206646, 917505, 65234, '<td valign="top">Darned hummingbirds are such showoffs!</td>', 'Darned hummingbirds are such showoffs!', '2010-11-01 09:48:16.000000', NULL, 1),
(6206649, 917399, 65234, '<td valign="top">Half the time all I see is a white tail disappearing into the distance.  Not blown away by this but it is certainly typical to find a deer attempting to be invisible in the woods.</td>', 'Half the time all I see is a white tail disappearing into the distance.  Not blown away by this but it is certainly typical to find a deer attempting to be invisible in the woods.', '2010-11-01 09:49:37.000000', NULL, 1),
(6206652, 917246, 65234, '<td valign="top">The background light is nicely positioned.  I would prefer the eye in sharper focus.  And ... it''s a bug.  Not what the challenge called for.</td>', 'The background light is nicely positioned.  I would prefer the eye in sharper focus.  And ... it''s a bug.  Not what the challenge called for.', '2010-11-01 09:52:15.000000', NULL, 1),
(6206655, 917455, 65234, '<td valign="top">Nice pose.  Light is somewhat flatter than I like.</td>', 'Nice pose.  Light is somewhat flatter than I like.', '2010-11-01 09:52:46.000000', NULL, 1),
(6206658, 917456, 65234, '<td valign="top">Interesting pose.  Shot is a bit busy so the deer doesn''t stand out exceptionally well but I know the deer prefer it that way.</td>', 'Interesting pose.  Shot is a bit busy so the deer doesn''t stand out exceptionally well but I know the deer prefer it that way.', '2010-11-01 09:55:34.000000', NULL, 1),
(6206662, 917319, 65234, '<td valign="top">Cute pose.  The geese look like they''re suffering from extreme noise reduction but the water is quite sharp.</td>', 'Cute pose.  The geese look like they''re suffering from extreme noise reduction but the water is quite sharp.', '2010-11-01 09:57:07.000000', NULL, 1),
(6206671, 917353, 65234, '<td valign="top">Now I''m going to have that song stuck in my head!  Nice of the deer to pose in a clearing for you.  Looks slightly over-bright on my screen.</td>', 'Now I''m going to have that song stuck in my head!  Nice of the deer to pose in a clearing for you.  Looks slightly over-bright on my screen.', '2010-11-01 09:58:47.000000', NULL, 1),
(6206678, 917451, 65234, '<td valign="top">Interesting place to find a butterfly.  But ... it''s a bug.</td>', 'Interesting place to find a butterfly.  But ... it''s a bug.', '2010-11-01 10:01:15.000000', NULL, 1),
(6206683, 917447, 65234, '<td valign="top">Nice portrait-y pose and DOF.  His head is a bit too dark on my screen to really see details as well as I''d like.</td>', 'Nice portrait-y pose and DOF.  His head is a bit too dark on my screen to really see details as well as I''d like.', '2010-11-01 10:05:29.000000', NULL, 1),
(6206685, 917351, 65234, '<td valign="top">I don''t trust that smile one bit!  He looks a bit blue to me.</td>', 'I don''t trust that smile one bit!  He looks a bit blue to me.', '2010-11-01 10:06:09.000000', NULL, 1),
(6206691, 916926, 65234, '<td valign="top">With some nice fall colors in the background.  Like the DOF.</td>', 'With some nice fall colors in the background.  Like the DOF.', '2010-11-01 10:09:01.000000', NULL, 1),
(6206693, 917280, 65234, '<td valign="top">Lovely light, DOF, detail, and very dynamic pose.  I feel I should go hide, and quickly!</td>', 'Lovely light, DOF, detail, and very dynamic pose.  I feel I should go hide, and quickly!', '2010-11-01 10:09:49.000000', NULL, 1),
(6206697, 916944, 65234, '<td valign="top">I only see these guys at the zoo.  They are very cool birds.  Composition doesn''t really engage me (he appears to be looking at the bottom of the frame with disinterest) but I don''t know if you had enough negative space around him to rotate and crop differently.</td>', 'I only see these guys at the zoo.  They are very cool birds.  Composition doesn''t really engage me (he appears to be looking at the bottom of the frame with disinterest) but I don''t know if you had enough negative space around him to rotate and crop differently.', '2010-11-01 10:13:51.000000', NULL, 1),
(6206698, 917272, 65234, '<td valign="top">Pretty bird!  Nice detail and I like the soft green of the background.</td>', 'Pretty bird!  Nice detail and I like the soft green of the background.', '2010-11-01 10:14:14.000000', NULL, 1),
(6206699, 917347, 65234, '<td valign="top">They look almost reluctant to engage in this fight.  Nice to find a moment like this for a wildlife challenge!</td>', 'They look almost reluctant to engage in this fight.  Nice to find a moment like this for a wildlife challenge!', '2010-11-01 10:16:05.000000', NULL, 1),
(6206700, 917119, 65234, '<td valign="top">Lovely light and detail; having the sky as the background makes me feel like I''m up on a mountaintop, even though I can''t see a bit of mountain.</td>', 'Lovely light and detail; having the sky as the background makes me feel like I''m up on a mountaintop, even though I can''t see a bit of mountain.', '2010-11-01 10:16:49.000000', NULL, 1),
(6206702, 917108, 65234, '<td valign="top">Cute, and you got nice light, but it''s still a toy and they tend to be less challenging to capture than live wildlife.</td>', 'Cute, and you got nice light, but it''s still a toy and they tend to be less challenging to capture than live wildlife.', '2010-11-01 10:18:45.000000', NULL, 1),
(6206704, 917103, 65234, '<td valign="top">Very nice stop-action on the lead goose.  Not sure what I think of the partial goose; I might have cropped/cloned to get rid of him.</td>', 'Very nice stop-action on the lead goose.  Not sure what I think of the partial goose; I might have cropped/cloned to get rid of him.', '2010-11-01 10:20:22.000000', NULL, 1),
(6206705, 916728, 115644, '<td valign="top">tripped out! I love this picture however the dark spot with no feathers and the center-right alignment take away from the image. my guess is that you had to shoot from an angle so that the center tail area can be seen. 8</td>', 'tripped out! I love this picture however the dark spot with no feathers and the center-right alignment take away from the image. my guess is that you had to shoot from an angle so that the center tail area can be seen. 8', '2010-11-01 10:22:22.000000', NULL, 1),
