(6208281, 917347, 111666, '<td valign="top">great timing on the shot :)</td>', 'great timing on the shot :)', '2010-11-02 08:35:32.000000', NULL, 1),
(6208301, 917235, 114225, '<td valign="top">Great photo! The tree in the background hidden by what looks like fog, the great amount of sharpness, and the good subjects all combine to make this spectacular.</td>', 'Great photo! The tree in the background hidden by what looks like fog, the great amount of sharpness, and the good subjects all combine to make this spectacular.', '2010-11-02 08:50:12.000000', NULL, 1),
(6208306, 916944, 114225, '<td valign="top">Nice subject, those colors are very cool (especially the eye). Unfortunately, the photo isn''t as sharp as I would like, which is really hurting the shot. The tight crop is good, and the composition is ok (would be better if you were lower to the ground).</td>', 'Nice subject, those colors are very cool (especially the eye). Unfortunately, the photo isn''t as sharp as I would like, which is really hurting the shot. The tight crop is good, and the composition is ok (would be better if you were lower to the ground).', '2010-11-02 08:51:40.000000', NULL, 1),
(6208309, 917230, 114225, '<td valign="top">Nice portrait. I like the tight crop and center composition here. Also, a nice amount of details. Interestingly enough, I think the thing that''s hurting this photo is just that he''s an average young buck. If he was majestic with large antlers, it would have really helped.</td>', 'Nice portrait. I like the tight crop and center composition here. Also, a nice amount of details. Interestingly enough, I think the thing that''s hurting this photo is just that he''s an average young buck. If he was majestic with large antlers, it would have really helped.', '2010-11-02 08:53:08.000000', NULL, 1),
(6208310, 916956, 114225, '<td valign="top">I like the composition, crop, and colors of this photo. I''m definitely not liking what appears to be the post processing that is smoothing out chunks of fur and removing the nice details it seems you had.</td>', 'I like the composition, crop, and colors of this photo. I''m definitely not liking what appears to be the post processing that is smoothing out chunks of fur and removing the nice details it seems you had.', '2010-11-02 08:54:24.000000', NULL, 1),
